// Esperamos: { email, nombre, producto, con_instalacion, stripe_customer_id }
const body = $input.item.json.body || $input.item.json;
if (!body.email || !body.producto) throw new Error('email y producto requeridos');

return {
  email: body.email.toLowerCase().trim(),
  nombre: body.nombre || '',
  producto: body.producto,
  con_instalacion: !!body.con_instalacion,
  stripe_customer_id: body.stripe_customer_id || null,
  fecha_compra: new Date().toISOString().split('T')[0]
};

